using TdLib.TdApi;
using TdLib.TdApi.Objects;
namespace TdLib.Api.OpenTelemetry;
/// <summary>
/// Autogenerated TDLib APIs
/// </summary>

public partial class ClientOpenTelemetryDecorator
{
    /// <summary>
    /// Returns detailed revenue statistics about a chat. Currently, this method can be used only
    /// for channels if supergroupFullInfo.can_get_revenue_statistics == true or bots if userFullInfo.bot_info.can_get_revenue_statistics == true
    /// </summary>
    public Task<TdLib.TdApi.Objects.ChatRevenueStatistics> GetChatRevenueStatisticsAsync(long chatId = default, bool isDark = default)
    {

           using var activity =  StartCallActivity("GetChatRevenueStatisticsAsync", typeof(GetChatRevenueStatistics).FullName ?? "GetChatRevenueStatisticsAsync");

           try
           {
             return client.GetChatRevenueStatisticsAsync(chatId, isDark);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
}
